/// Native replay implementations for accessibility bindings.
#[inline]
fn destack_accessibility_action_close_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    handle: resource::AccessibilityActionHandle,
) -> RuntimeResult<()> {
    let _ = &handle;

    binding.trace().run_binding_without_context(
        ACCESSIBILITY_ACTION_CLOSE,
        binding.replay_payload_for(ACCESSIBILITY_ACTION_CLOSE)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_accessibility_action_close(binding, handle)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_accessibility_action_close(binding, handle)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = AccessibilityActionCloseReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    AccessibilityActionCloseReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

#[inline]
fn destack_accessibility_action_open_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut resource::AccessibilityActionHandle,
    window: resource::WindowHandle,
    options: AccessibilityActionOpenOptions,
) -> RuntimeResult<()> {
    let _ = (&window, &options);

    binding.trace().run_binding_without_context(
        ACCESSIBILITY_ACTION_OPEN,
        binding.replay_payload_for(ACCESSIBILITY_ACTION_OPEN)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_accessibility_action_open(binding, out, window, options)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_accessibility_action_open(
                    binding, out, window, options,
                )
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: resource::AccessibilityActionHandle = unsafe { out.read() };
                let result_recorded = result_value;
                let payload = AccessibilityActionOpenReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    AccessibilityActionOpenReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    unsafe { out.write(value) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

