#[inline]
fn destack_accessibility_tree_apply_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    window: resource::WindowHandle,
    update: AccessibilityTreeUpdate,
) -> RuntimeResult<()> {
    let _ = (&window, &update);

    binding.trace().run_binding_without_context(
        ACCESSIBILITY_TREE_APPLY,
        binding.replay_payload_for(ACCESSIBILITY_TREE_APPLY)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_accessibility_tree_apply(binding, window, update)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_accessibility_tree_apply(
                    binding, window, update,
                )
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = AccessibilityTreeApplyReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    AccessibilityTreeApplyReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

