/// Native export wrappers for accessibility bindings.
#[unsafe(export_name = "destack.accessibility.action.close")]
pub(crate) unsafe extern "C" fn destack_accessibility_action_close(
    handle: resource::AccessibilityActionHandle,
) -> RuntimeStatus {
    native_call(|context| {
        let _ = &handle;

        let (world, _binding_hook_guard) =
            context.on_before_binding_resolve_world(ACCESSIBILITY_ACTION_CLOSE)?;
        destack_accessibility_action_close_replay(context, world, handle)
    })
}

#[unsafe(export_name = "destack.accessibility.action.open")]
