#[inline]
fn destack_accessibility_tree_apply_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    window: resource::WindowHandle,
    update: AccessibilityTreeUpdateVm,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        ACCESSIBILITY_TREE_APPLY,
        binding.replay_payload_for(ACCESSIBILITY_TREE_APPLY)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_accessibility_tree_apply(binding, context, window, update)
            }
            RuntimeWorld::Simulation => platform_simulation_vm::destack_accessibility_tree_apply(
                binding, context, window, update,
            ),
        },
        |context, result| {
            let _ = &context;
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = AccessibilityTreeApplyReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    AccessibilityTreeApplyReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let _ = &context;
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_accessibility_tree_apply_result(context, result)?;
    Ok(result)
}

