/// Register VM bindings for accessibility.
pub(crate) fn register_accessibility_vm_bindings(
    registry: &mut BindingRegistry,
    isolate: &mut Isolate,
) {
    {
        binding!(
            registry,
            isolate,
            ACCESSIBILITY_ACTION_CLOSE,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (handle,) = decode_destack_accessibility_action_close_args(context, args)?;

                    // execute binding
                    let (world, _binding_hook_guard) =
                        binding.on_before_binding_resolve_world(ACCESSIBILITY_ACTION_CLOSE)?;
                    destack_accessibility_action_close_vm_replay(binding, context, world, handle)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            ACCESSIBILITY_ACTION_OPEN,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (window, options) =
                        decode_destack_accessibility_action_open_args(context, args)?;

                    // execute binding
                    let (world, _binding_hook_guard) =
                        binding.on_before_binding_resolve_world(ACCESSIBILITY_ACTION_OPEN)?;
                    destack_accessibility_action_open_vm_replay(
                        binding, context, world, window, options,
                    )
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            ACCESSIBILITY_ACTION_READ,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (handle, timeoutns) =
                        decode_destack_accessibility_action_read_args(context, args)?;

                    // execute binding
                    let (world, _binding_hook_guard) =
                        binding.on_before_binding_resolve_world(ACCESSIBILITY_ACTION_READ)?;
                    destack_accessibility_action_read_vm_replay(
                        binding, context, world, handle, timeoutns,
                    )
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            ACCESSIBILITY_ACTION_TRY_READ,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (handle,) =
                        decode_destack_accessibility_action_try_read_args(context, args)?;

                    // execute binding
                    let (world, _binding_hook_guard) =
                        binding.on_before_binding_resolve_world(ACCESSIBILITY_ACTION_TRY_READ)?;
                    destack_accessibility_action_try_read_vm_replay(binding, context, world, handle)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            ACCESSIBILITY_TREE_APPLY,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (window, update) =
                        decode_destack_accessibility_tree_apply_args(context, args)?;

                    // execute binding
                    let (world, _binding_hook_guard) =
                        binding.on_before_binding_resolve_world(ACCESSIBILITY_TREE_APPLY)?;
                    destack_accessibility_tree_apply_vm_replay(
                        binding, context, world, window, update,
                    )
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            ACCESSIBILITY_TREE_CLEAR,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (window,) = decode_destack_accessibility_tree_clear_args(context, args)?;

                    // execute binding
                    let (world, _binding_hook_guard) =
                        binding.on_before_binding_resolve_world(ACCESSIBILITY_TREE_CLEAR)?;
                    destack_accessibility_tree_clear_vm_replay(binding, context, world, window)
                })
                .map_err(Into::into)
            }
        );
    }
}

/// Install VM bindings for accessibility.
pub(crate) fn install_accessibility_vm_bindings(
    registry: &mut BindingRegistry,
    isolate: &mut Isolate,
) {
    register_accessibility_vm_bindings(registry, isolate);
}

vm_binding_set!(pub(crate) ACCESSIBILITY_VM_BINDINGS, "accessibility", install_accessibility_vm_bindings);
